from pathlib import Path
import subprocess,json,shutil
r=Path.cwd()
def git(*a):return subprocess.check_output(['git',*a],text=True).strip()
audit=json.loads((r/'build/publication-audit112.json').read_text(encoding='utf8'));assert audit['passed'] and audit['remoteFetched']
release=git('rev-parse','readme-112^{commit}');assert release==audit['commit']==git('rev-parse','HEAD');tag=git('rev-parse','readme-112')
analysis=json.loads((r/'build/analysis112.json').read_text(encoding='utf8'));assert analysis['passed']
verification=json.loads((r/'docs/readmes/112/verification.json').read_text(encoding='utf8'))
data={'edition':112,'releaseCommit':release,'annotatedTag':'readme-112','tagObject':tag,'audit':audit,'analysis':analysis,'releaseCI':json.loads((r/'build/ci112-release.json').read_text(encoding='utf8')),'scope':'Actual non-force main/edition112/tag push, fetched and audited. Exact completed-chat snapshots with stable read-only IDs and original source/outcome checks. Active24 chat limit unchanged; unfinished tasks retained. CI separate.'}
(r/'docs/PUBLICATION_112.json').write_text(json.dumps(data,indent=2)+'\n',encoding='utf8')
folder=r/'docs/publication112';folder.mkdir(exist_ok=True)
names=['ci112-release.json','publication-audit112.json','push112.log','release112.log','release112.py','audit-publication112.py','publication112.py','finish-publication112.py','freeze112.py','check-guide112.cjs','visual112.json','visual-review112.json','documentation-check.json','doc-check112.log','guide112.log','guide112-1440.png','guide112-390.png','ci112-parent.json','analysis112.json','compile112.log','java112-final.log','correction112.json','java112-initial.log','archive112.log','archive112-final.log','archive112-verified.log','study095-build-initial112.json','recorder-correction112.json','inspect112.log','desktop112.log','desktop112-additional.log','source-identity112.json']
for name in names:assert (r/'build'/name).is_file(),name;shutil.copyfile(r/'build'/name,folder/name)
notice=f"Published release {release}; annotated readme-112 tag object {tag}. Actual main/edition112/tag push fetched and verified: {audit['canonicalSourceFiles']} canonical sources, {audit['frozenHashes']} frozen hashes across112 editions and {audit['original112EvidenceFiles']} original archive entries. "
validation=f"{verification['javaMethods']} Java methods,148 desktop checks and20 altered-evidence refusals pass. Actual23 exact chat archives, three cancelled tasks retained, two fresh chat completions and one abrupt recovery;24 saved procedures. Active24 chat limit unchanged. Original checked checkpoint bytes, full journals and fresh source/outcome checks retained. Original goal/workflow/qualification verifiers unchanged. Initial35/36 regression and explicit-refusal correction preserved. First actual attempt refused recorder authority during recovery; original146.783s attempt retained, recorder-only correction retained. Second attempt passed both chats and recovery, then corrected test expectation for preserved immutable dataset version1; History selection corrected and full cohort rerun. Actual History controls/screenshots. Preserve private worlds and frozen editions; no delegation. "
for name,link in [('AGENTS.md','docs/PUBLICATION_112.json'),('README-CONTRIBUTORS.md','docs/PUBLICATION_112.json'),('docs/PROJECT_MEMORY.md','PUBLICATION_112.json'),('docs/DEVELOPMENT_LOG.md','PUBLICATION_112.json'),('docs/ARCHITECTURE.md','PUBLICATION_112.json')]:
 p=r/name;s=p.read_text(encoding='utf8');assert '## Edition112 — validated chat archival' in s;s=s.replace('## Edition112 — validated chat archival','## Edition112 — published and fetched back\n\n'+notice+validation+'[Publication receipt]('+link+').',1).replace('Publication pending actual push/fetch; CI separate.','Main/tag publication and fetched verification completed; remote CI is recorded separately.',1);p.write_text(s,encoding='utf8',newline='\n')
p=r/'README.md';p.write_text(p.read_text(encoding='utf8')+'\nPublished to main. [Edition112 fetched GitHub verification](docs/PUBLICATION_112.json).\n',encoding='utf8',newline='\n')
p=r/'docs/obsidian/120-completed-chat-history.md';p.write_text(p.read_text(encoding='utf8').replace('Publication pending actual push/fetch; CI separate.','Publication and fetched verification completed; CI separate.')+'\n'+notice+validation+'[[docs/PUBLICATION_112.json|Publication receipt]]\n',encoding='utf8',newline='\n')
print(notice)
